<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas Report Copilot</title><style>body{font:16px system-ui;background:#101827;color:#eef;padding:24px;max-width:800px;margin:auto}input,textarea,select{display:block;width:100%;padding:12px;margin:8px 0 16px;background:#17243a;color:#fff;border:1px solid #40516c;border-radius:8px;box-sizing:border-box}button{padding:12px 18px;background:#9cebd7;border:0;border-radius:8px;font-weight:bold}pre{white-space:pre-wrap;background:#17243a;padding:16px;border-radius:10px}</style></head><body><h1>Project Atlas</h1><p>Entitlement-aware market research assistant</p><form id="f"><label>Client</label><select name="client_id"><option>C-01</option><option>C-02</option></select><label>Question</label><textarea name="question" minlength="3" maxlength="4000" required></textarea><button>Ask Atlas</button></form><h2>Answer</h2><pre id="result">Your cited response will appear here.</pre><script>document.getElementById('f').addEventListener('submit',async e=>{e.preventDefault();let fd=new FormData(e.target);let out=document.getElementById('result');out.textContent='Working…';try{let r=await fetch('<?=site_url('atlas/ask')?>',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:fd});let j=await r.json();out.textContent=JSON.stringify(j,null,2)}catch(_){out.textContent='Service unavailable. Please try again or contact an analyst.'}});</script></body></html>